export const escapeText=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const icon=name=>`<svg aria-hidden="true"><use href="#${escapeText(name)}"/></svg>`;
export function imageMarkup(d,{className='',lazy=true}={}){if(!d.image)return `<span class="empty-plate" role="img" aria-label="${escapeText(d.name)}，暂缺示意图片">暂缺图片</span>`;const thumb=d.thumbnail??d.image,fit=d.imageFit??{},num=(v,min,max,fallback)=>Number.isFinite(v)?Math.min(max,Math.max(min,v)):fallback;return `<img src="${escapeText(thumb)}" ${d.thumbnail?`srcset="${escapeText(thumb)} 320w, ${escapeText(d.image)} 768w" sizes="(max-width:760px) 44vw, 250px"`:''} width="768" height="768" alt="${escapeText(d.name)}，餐品示意，非窗口实拍" ${lazy?'loading="lazy"':''} decoding="async" class="${escapeText(className)}" style="--food-scale:${num(fit.scale,.9,1.14,1)};--food-x:${num(fit.x,-10,10,0)}%;--food-y:${num(fit.y,-10,10,0)}%"><span class="image-failed" hidden>${icon('bowl')}<span>图片暂未加载，文字信息仍可查看</span></span>`;}
export function wireImages(root){root.querySelectorAll('img:not([data-wired])').forEach(img=>{img.dataset.wired='1';const fail=()=>{img.classList.remove('image-loading');img.hidden=true;const fallback=img.nextElementSibling;if(fallback?.classList.contains('image-failed'))fallback.hidden=false;};if(!img.complete)img.classList.add('image-loading');img.addEventListener('load',()=>img.classList.remove('image-loading'),{once:true});img.addEventListener('error',fail,{once:true});if(img.complete&&!img.naturalWidth)fail();});}
